export interface Frontmatter {
  title: string;
  date?: Date;
  tags?: string[];
  draft?: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface Page {
  path: string;
  frontmatter: Frontmatter;
  content: string;
  html: string;
  url: string;
}

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  siteTitle: string;
  siteUrl: string;
}

export interface TagMap {
  [tag: string]: Page[];
}

import matter from "gray-matter";
import { Frontmatter } from "./types.js";

export function parseFrontmatter(markdown: string): {
  frontmatter: Frontmatter;
  content: string;
} {
  const { data, content } = matter(markdown);

  const frontmatter: Frontmatter = {
    title: data.title ?? "Untitled",
  };

  if (data.date) {
    const d = new Date(data.date);
    if (!isNaN(d.getTime())) frontmatter.date = d;
  }

  if (data.tags) {
    frontmatter.tags = Array.isArray(data.tags)
      ? data.tags.map((t: unknown) => String(t))
      : String(data.tags)
          .split(",")
          .map((t) => t.trim())
          .filter(Boolean);
  }

  if (data.draft !== undefined) {
    frontmatter.draft = Boolean(data.draft);
  }

  if (typeof data.layout === "string") {
    frontmatter.layout = data.layout;
  }

  return { frontmatter, content };
}

import Handlebars from "handlebars";
import { readFileSync, readdirSync, existsSync } from "node:fs";
import { join, extname } from "node:path";
import { Page, SiteConfig } from "./types.js";

export function loadTemplates(config: SiteConfig): {
  layouts: Map<string, Handlebars.TemplateDelegate>;
  renderPage: (page: Page, pages: Page[]) => string;
} {
  const layouts = new Map<string, Handlebars.TemplateDelegate>();

  registerPartials(config.templateDir);
  registerLayouts(config.templateDir, layouts);

  function renderPage(page: Page, pages: Page[]): string {
    const layoutName = page.frontmatter.layout ?? "default";
    const layout = layouts.get(layoutName);

    const templateData = {
      ...page.frontmatter,
      content: page.html,
      page,
      pages: pages.filter((p) => !p.frontmatter.draft),
      site: { title: config.siteTitle },
    };

    if (layout) {
      return layout(templateData);
    }

    return page.html;
  }

  return { layouts, renderPage };
}

function registerPartials(templateDir: string): void {
  const partialsDir = join(templateDir, "partials");
  if (!existsSync(partialsDir)) return;

  for (const file of readdirSync(partialsDir)) {
    if (!file.endsWith(".hbs") && !file.endsWith(".handlebars")) continue;
    const name = file.replace(/\.(hbs|handlebars)$/, "");
    const source = readFileSync(join(partialsDir, file), "utf-8");
    Handlebars.registerPartial(name, source);
  }
}

function registerLayouts(
  templateDir: string,
  layouts: Map<string, Handlebars.TemplateDelegate>
): void {
  if (!existsSync(templateDir)) return;

  for (const file of readdirSync(templateDir)) {
    const ext = extname(file);
    if (ext !== ".hbs" && ext !== ".handlebars") continue;
    const name = file.replace(/\.(hbs|handlebars)$/, "");
    const source = readFileSync(join(templateDir, file), "utf-8");
    layouts.set(name, Handlebars.compile(source));
  }
}

import hljs from "highlight.js";

const LANG_RE = /^language-(\S+)/;

export function highlightCode(html: string): string {
  return html.replace(/<pre><code class="([^"]*)">([\s\S]*?)<\/code><\/pre>/g, (match, classes, code) => {
    const m = classes.match(LANG_RE);
    if (!m) return match;

    const lang = m[1];
    let highlighted: string;

    try {
      if (hljs.getLanguage(lang)) {
        highlighted = hljs.highlight(decodeEntities(code), { language: lang }).value;
      } else {
        highlighted = hljs.highlightAuto(decodeEntities(code)).value;
      }
    } catch {
      return match;
    }

    return `<pre><code class="hljs ${classes}">${highlighted}</code></pre>`;
  });
}

function decodeEntities(text: string): string {
  return text
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

import { Page, SiteConfig } from "./types.js";

export function generateRss(pages: Page[], config: SiteConfig): string {
  const posts = pages
    .filter((p) => !p.frontmatter.draft && p.frontmatter.date)
    .sort((a, b) => (b.frontmatter.date!.getTime() - a.frontmatter.date!.getTime()));

  const items = posts.map((p) => {
    const title = escapeXml(p.frontmatter.title);
    const link = `${config.siteUrl}/${p.url}`;
    const date = p.frontmatter.date!.toUTCString();
    const description = escapeXml(p.html.slice(0, 500));

    return `    <item>
      <title>${title}</title>
      <link>${link}</link>
      <guid isPermaLink="true">${link}</guid>
      <pubDate>${date}</pubDate>
      <description>${description}</description>
    </item>`;
  });

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.siteTitle)}</title>
    <link>${config.siteUrl}</link>
    <description>${escapeXml(config.siteTitle)}</description>
    <atom:link href="${config.siteUrl}/rss.xml" rel="self" type="application/rss+xml"/>
${items.join("\n")}
  </channel>
</rss>`;
}

function escapeXml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

import { Page, TagMap, SiteConfig } from "./types.js";

export function buildTagMap(pages: Page[]): TagMap {
  const map: TagMap = {};

  for (const page of pages) {
    if (page.frontmatter.draft) continue;
    const tags = page.frontmatter.tags ?? [];
    for (const tag of tags) {
      if (!map[tag]) map[tag] = [];
      map[tag].push(page);
    }
  }

  return map;
}

export function generateTagPages(
  tagMap: TagMap,
  renderPage: (page: Page, pages: Page[]) => string,
  _config: SiteConfig
): Page[] {
  const tagPages: Page[] = [];
  const allPages = Object.values(tagMap).flat();

  for (const [tag, pages] of Object.entries(tagMap)) {
    const listHtml = pages
      .map((p) => `<li><a href="/${p.url}">${p.frontmatter.title}</a></li>`)
      .join("\n");

    const fullHtml = `<h1>Tag: ${tag}</h1>\n<ul>\n${listHtml}\n</ul>`;

    const tagPage: Page = {
      path: `tags/${slugify(tag)}.html`,
      frontmatter: {
        title: `Tag: ${tag}`,
        layout: "default",
      },
      content: "",
      html: fullHtml,
      url: `tags/${slugify(tag)}.html`,
    };

    tagPages.push(tagPage);
  }

  return tagPages.map((p) => ({
    ...p,
    html: renderPage(p, allPages),
  }));
}

function slugify(s: string): string {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

import { readFileSync, readdirSync, mkdirSync, writeFileSync, existsSync } from "node:fs";
import { join, relative, dirname, extname } from "node:path";
import { marked } from "marked";
import { SiteConfig, Page } from "./types.js";
import { parseFrontmatter } from "./frontmatter.js";
import { loadTemplates } from "./templates.js";
import { highlightCode } from "./highlighting.js";
import { generateRss } from "./rss.js";
import { buildTagMap, generateTagPages } from "./tags.js";

export function build(config: SiteConfig): void {
  const { renderPage } = loadTemplates(config);

  const pages = collectPages(config);
  const published = pages.filter((p) => !p.frontmatter.draft);

  const tagMap = buildTagMap(published);
  const tagPages = generateTagPages(tagMap, renderPage, config);

  for (const page of [...published, ...tagPages]) {
    page.html = renderPage(page, published);
    writeOutput(page, config);
  }

  const rss = generateRss(published, config);
  mkdirSync(config.outputDir, { recursive: true });
  writeFileSync(join(config.outputDir, "rss.xml"), rss);
}

function collectPages(config: SiteConfig): Page[] {
  const pages: Page[] = [];

  function walk(dir: string): void {
    if (!existsSync(dir)) return;
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
      } else if (entry.name.endsWith(".md")) {
        const page = processMarkdownFile(full, config);
        if (page) pages.push(page);
      }
    }
  }

  walk(config.sourceDir);
  return pages;
}

function processMarkdownFile(filePath: string, config: SiteConfig): Page | null {
  const raw = readFileSync(filePath, "utf-8");
  const { frontmatter, content } = parseFrontmatter(raw);

  const relPath = relative(config.sourceDir, filePath);
  const url = relPath.replace(/\.md$/, ".html");
  const outPath = relPath.replace(/\.md$/, ".html");

  let html = marked.parse(content) as string;
  html = highlightCode(html);

  return {
    path: outPath,
    frontmatter,
    content,
    html,
    url,
  };
}

function writeOutput(page: Page, config: SiteConfig): void {
  const outPath = join(config.outputDir, page.path);
  mkdirSync(dirname(outPath), { recursive: true });
  writeFileSync(outPath, page.html);
}

import { createServer, IncomingMessage, ServerResponse } from "node:http";
import { readFileSync, existsSync, statSync } from "node:fs";
import { join, extname } from "node:path";
import { WebSocketServer, WebSocket } from "ws";
import { SiteConfig } from "./types.js";
import { build } from "./build.js";

const RELOAD_SCRIPT = `
<script>
(function() {
  var ws = new WebSocket('ws://' + location.host);
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
  ws.onclose = function() {
    setTimeout(function() {
      location.reload();
    }, 2000);
  };
})();
</script>`;

let wss: WebSocketServer;

export function startDevServer(config: SiteConfig, port: number = 3000): void {
  const server = createServer((req: IncomingMessage, res: ServerResponse) => {
    handleRequest(req, res, config);
  });

  wss = new WebSocketServer({ server });

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}`);
  });
}

export function reloadClients(): void {
  if (!wss) return;
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send("reload");
    }
  });
}

const MIME: Record<string, string> = {
  ".html": "text/html",
  ".css": "text/css",
  ".js": "application/javascript",
  ".json": "application/json",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".xml": "application/xml",
};

function handleRequest(
  req: IncomingMessage,
  res: ServerResponse,
  config: SiteConfig
): void {
  let urlPath = req.url ?? "/";
  if (urlPath === "/") urlPath = "/index.html";

  const filePath = join(config.outputDir, urlPath);

  if (!existsSync(filePath) || !statSync(filePath).isFile()) {
    res.writeHead(404);
    res.end("Not found");
    return;
  }

  const ext = extname(filePath);
  const contentType = MIME[ext] ?? "application/octet-stream";

  let body = readFileSync(filePath);

  if (contentType === "text/html") {
    const html = body.toString("utf-8");
    const injected = html.replace("</body>", `${RELOAD_SCRIPT}</body>`);
    res.writeHead(200, {
      "Content-Type": "text/html",
      "Content-Length": Buffer.byteLength(injected),
    });
    res.end(injected);
  } else {
    res.writeHead(200, {
      "Content-Type": contentType,
      "Content-Length": body.length,
    });
    res.end(body);
  }
}

import { watch, FSWatcher } from "chokidar";
import { SiteConfig } from "./types.js";
import { build } from "./build.js";
import { reloadClients } from "./dev-server.js";

export function startWatcher(config: SiteConfig): FSWatcher {
  build(config);
  console.log("Initial build complete.");

  const watcher = watch([config.sourceDir, config.templateDir], {
    ignoreInitial: true,
    ignored: /(^|[\/\\])\../,
  });

  let debounce: ReturnType<typeof setTimeout> | null = null;

  watcher.on("all", (event, path) => {
    if (debounce) clearTimeout(debounce);
    debounce = setTimeout(() => {
      console.log(`Change detected: ${event} ${path}`);
      build(config);
      reloadClients();
    }, 200);
  });

  return watcher;
}

#!/usr/bin/env node
import { Command } from "commander";
import { resolve } from "node:path";
import { build } from "./build.js";
import { startDevServer } from "./dev-server.js";
import { startWatcher } from "./watcher.js";

const program = new Command();

program
  .name("ssg")
  .description("Static site generator")
  .option("-s, --source <dir>", "source directory of Markdown files", "content")
  .option("-t, --templates <dir>", "template directory of Handlebars files", "templates")
  .option("-o, --output <dir>", "output directory for generated HTML", "public")
  .option("--site-title <title>", "site title", "My Site")
  .option("--site-url <url>", "site base URL", "http://localhost:3000");

program
  .command("build")
  .description("Build the static site")
  .action(() => {
    const opts = program.opts();
    const config = {
      sourceDir: resolve(opts.source),
      templateDir: resolve(opts.templates),
      outputDir: resolve(opts.output),
      siteTitle: opts.siteTitle,
      siteUrl: opts.siteUrl,
    };
    build(config);
    console.log(`Site built to ${config.outputDir}`);
  });

program
  .command("dev")
  .description("Start dev server with live reload")
  .option("-p, --port <port>", "port to listen on", "3000")
  .action((cmdOpts) => {
    const opts = program.opts();
    const config = {
      sourceDir: resolve(opts.source),
      templateDir: resolve(opts.templates),
      outputDir: resolve(opts.output),
      siteTitle: opts.siteTitle,
      siteUrl: `http://localhost:${cmdOpts.port}`,
    };
    startDevServer(config, parseInt(cmdOpts.port, 10));
    startWatcher(config);
  });

program.parse();

